comment.body:
Because this replaces the Radix Select with a custom role="radiogroup", we need to preserve radio keyboard behavior. Right now the buttons only work with click/Tab+Enter, but arrow keys/Home/End are expected for a radiogroup; adding roving focus keeps the new UI accessible.

```suggestion
              {SORT_MODES.map((mode, index) => {
                const ModeIcon = mode.icon;
                const isSelected = sortMode === mode.value;

                return (
                  <button
                    key={mode.value}
                    type="button"
                    role="radio"
                    aria-checked={isSelected}
                    tabIndex={isSelected ? 0 : -1}
                    data-testid={`search-sort-${mode.value}`}
                    onClick={() => setSortMode(mode.value)}
                    onKeyDown={(event) => {
                      const lastIndex = SORT_MODES.length - 1;
                      const nextIndexByKey: Partial<Record<string, number>> = {
                        ArrowRight: index === lastIndex ? 0 : index + 1,
                        ArrowDown: index === lastIndex ? 0 : index + 1,
                        ArrowLeft: index === 0 ? lastIndex : index - 1,
                        ArrowUp: index === 0 ? lastIndex : index - 1,
                        Home: 0,
                        End: lastIndex,
                      };
                      const nextIndex = nextIndexByKey[event.key];

                      if (nextIndex === undefined) return;

                      event.preventDefault();
                      setSortMode(SORT_MODES[nextIndex].value);
                      event.currentTarget.parentElement
                        ?.querySelectorAll<HTMLButtonElement>('[role="radio"]')
                        .item(nextIndex)
                        ?.focus();
                    }}
                    className={`
                      flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all
                      ${isSelected
                        ? 'bg-primary text-primary-foreground shadow-md'
                        : 'bg-brand-light-green dark:bg-brand-dark-green hover:bg-muted text-muted-foreground hover:text-foreground'
                      }
                    `}
                  >
                    <ModeIcon className="h-4 w-4" />
                    <span>{mode.label}</span>
                  </button>
                );
              })}
```

